import{_ as e,o as t,c as l,aj as o}from"./chunks/framework.C18smN11.js";const q=JSON.parse('{"title":"更新日志","description":"","frontmatter":{"title":"更新日志"},"headers":[],"relativePath":"qiantao/changelog.md","filePath":"qiantao/changelog.md","lastUpdated":1792576248000}'),i={name:"qiantao/changelog.md"};function d(r,a,n,h,c,s){return t(),l("div",null,[...a[0]||(a[0]=[o('<h1 id="klkhk-plugin-qiandao-1-12-2-·-更新日志" tabindex="-1">[klkhk]plugin_qiandao_1.12.2 · 更新日志 <a class="header-anchor" href="#klkhk-plugin-qiandao-1-12-2-·-更新日志" aria-label="Permalink to &quot;[klkhk]plugin_qiandao_1.12.2 · 更新日志&quot;">​</a></h1><h2 id="v1-1-4" tabindex="-1">v1.1.4 <a class="header-anchor" href="#v1-1-4" aria-label="Permalink to &quot;v1.1.4&quot;">​</a></h2><p><strong>当前版本</strong> · 适用 Minecraft 1.12.2</p><h3 id="新增" tabindex="-1">新增 <a class="header-anchor" href="#新增" aria-label="Permalink to &quot;新增&quot;">​</a></h3><ul><li>七日周期奖励，第 7 天终极大奖，第 8 天循环且连续天数继续累计</li><li>连续签到 7 / 14 / 30 天额外奖励，支持全服广播</li><li>补签卡系统：右键打开补签面板、二次确认、消耗 1 张补签卡、连续天数恢复</li><li>在线奖励：累计在线满设定时长自动发卡，每日上限</li><li>签到排行榜：右侧实时计分板 + <code>/qd rank</code> 图形化面板</li><li>三种经济联动：ZPoints / PlayerPoints / Vault</li><li>签到标题、音效、粒子特效、今日槽位附魔发光</li></ul><h3 id="优化" tabindex="-1">优化 <a class="header-anchor" href="#优化" aria-label="Permalink to &quot;优化&quot;">​</a></h3><ul><li>玩家数据异步定时保存，停服同步保存</li><li>自动清理 60 天前日期记录，防止 <code>data.yml</code> 膨胀</li><li>排行榜使用每位玩家独立计分板，不干扰主计分板</li><li>1.12.2 计分板 16 字符限制用 Team 前缀/后缀方案绕开</li></ul><h3 id="命令" tabindex="-1">命令 <a class="header-anchor" href="#命令" aria-label="Permalink to &quot;命令&quot;">​</a></h3><ul><li><code>/qd</code>、<code>/qd rank</code>、<code>/qd help</code>、<code>/qd givecard</code>、<code>/qd reload</code></li></ul><hr><h2 id="版本规则" tabindex="-1">版本规则 <a class="header-anchor" href="#版本规则" aria-label="Permalink to &quot;版本规则&quot;">​</a></h2><p><code>v主版本.次版本.修订号</code></p><table tabindex="0"><thead><tr><th>位</th><th>变化含义</th><th>兼容性</th></tr></thead><tbody><tr><td>主版本</td><td>架构或核心逻辑重构</td><td>配置可能不兼容</td></tr><tr><td>次版本</td><td>新增功能</td><td>配置向下兼容</td></tr><tr><td>修订号</td><td>问题修复、细节优化</td><td>完全兼容</td></tr></tbody></table><h2 id="升级注意" tabindex="-1">升级注意 <a class="header-anchor" href="#升级注意" aria-label="Permalink to &quot;升级注意&quot;">​</a></h2><ol><li>备份 <code>config.yml</code> 与 <code>data.yml</code></li><li>删除旧 <code>config.yml</code>，替换 jar</li><li>重启生成新配置</li><li>迁回自定义内容</li><li><code>/qd reload</code> 验证</li></ol><hr><p><a href="https://github.com/zhaobuobuo114/klkhk-plugin_qiandao/releases/latest" target="_blank" rel="noreferrer">下载最新版本</a> · <a href="/plugin-wiki/qiantao/">返回插件介绍</a></p>',17)])])}const k=e(i,[["render",d]]);export{q as __pageData,k as default};
